INSERT INTO membrane_retrofits(assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES
('A099-R1','R099-01','CN0371','acrylonitrile_900_design','screening',1,'维持金属回收及循环清洗','优先沉淀循环并监测累积；如有实际排浓需求再比较MF/UF或NF选择性处理，不盲目替换闭路','conditional','金属物料衡算、浓液合规去向、实际进水与经济性','S099-02','INFERRED；非已建方案','实际投运、分股水量、金属去向及循环累积、共享站接入和成本','分股采样、循环累积与金属衡算、预处理试验、同边界费用','维持/优化现有分质与非膜处理',NULL,NULL,NULL,NULL,NULL,NULL,'缺六维实证','2026-11-28'),
('A099-R2','R099-02','CN0371','shared_station_2016_recalled_2024','screening',1,'共享站回用评价','查现行共享站进水与回用需求，按水质及浓液去向评价深度膜回用','unknown','金属物料衡算、浓液合规去向、实际进水与经济性','S099-01','INFERRED；非已建方案','真实站能力、运行及进出水、膜、污泥和费用','分股采样、循环累积与金属衡算、预处理试验、同边界费用','维持/优化现有分质与非膜处理',NULL,NULL,NULL,NULL,NULL,NULL,'缺六维实证','2026-11-28');
INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N099-01','CN0371','S099-02','正式批复及开工运行限制','一、四（一）（五）（八）','3×300t/a；园区复核认定前不得启动生产，投产前有效污水协议；需论证既有厂内站及吉林石化站接纳；清洗水上清液回罐，沉淀物批复要求回焙烧，与环评表3.4-3回浆料配制描述不同，均保留，实际路径待核。截图502，正文可读。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N099-02','CN0371','S099-01','项目设计口径差异','3.3.3、3.4-3 p134–136、3.5-1/2','清洗80L/批、2批/d、330d，52.8m³/a；原文三线6批/d与该口径不闭合，不倍乘。3.3-6金属化合物呈碱性，3.4-3酸性pH4–5；按表号保留。车间地面3.3.3称卫生清洗水入站，p135称干吸尘不产生地面水，实验水不产生；待核。初雨0.9m³/次入年合计，频次未知。纯水制备2m³/h，多介质、活性炭、RO，80%制水率。3.5-1氨氮2.3895kg/a，3.5-2为0.002375t/a；不强配平。设计金属沉淀物9.52kg/a回用；气相高通量膜过滤不属废水。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N099-03','CN0371','S099-01','既有共享站历史工艺','p96–98，吉龙环建字〔2016〕17号落实对照','历史三相三维电化学→水解→接触氧化，接园区及吉林石化站；沉淀池污泥压滤外委吉林省固体废物处理有限责任公司，臭气活性炭经销商回收。在线监测及500m³事故池历史已建，未取当前实测。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N099-04','CN0134','W03S04','2023分股及达产源强独立提取','表3.4-1、3.4-4、3.6-1；政府同文件不同入口索引 https://www.zjxc.gov.cn/module/download/downfile.jsp?classid=0&filename=4554bbe80df748348402be46d4a22e23.pdf','19分股、2项目小计、全厂合计两套口径；2023项目1591.2+1108.8=2700t/a；达产2340+4343.6=6683.6t/a；原文各分股与小计有四舍五入差异，保留表值。表注2023铑炭/钌炭0；原文措辞疑漏否定，不补猜生产状态。浓度来自原环评非2023实测。历史排环境质量COD0.135、氨氮0.0135t/a，许可6689.8t/a、COD0.334、氨氮0.033；原环评审批质量0.3345/0.0334另有口径差。2022验收5526.6核算旧值不重复。提取车间浓缩脱盐后与其他水进30t/d中和混凝、物化沉淀、A/O、二沉，已有流程证据；截图附件超14MB限制，正文/检索表可读。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N099-05','CN0130','S099-03','2026H1运营及二期机会','经营情况回顾、关联交易','长兴基地公司称正常生产，二期处评价审核。集团H1向明境环保采购废物回收治理54000元，非特定厂污水成本，不入经济表。2025合资凯境为废物回收治理主体，无独立催化剂厂址证据，不新增制造厂。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N099-06','CN0130','S099-04','700t/a项目定位','企业新闻索引','公示稿及首次公示标题出现700吨工业催化材料项目；日期、产品分项、与二期技改关联及正文待核，不计已建规模。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N099-07','CN0275','S099-05','技改备案线索','2026索引','3.5万吨/年废催化剂综合利用技改项目索引有不准予许可字样，未得行政原件及理由，不判项目永久取消或既有生产停止；既有3.5万吨装置不重复。','WEB_SECONDARY','WEB_TEXT','2026-11-28');
